<?php
require_once __DIR__.'/accounting_cash.php';
function ac_ledger_filters(array $filters,string $alias='x'):array {
    $where=[];$params=[];
    foreach(['from','to'] as $key)if(!empty($filters[$key])){$where[]="$alias.transaction_date ".($key==='from'?'>=':'<=').' ?';$params[]=ac_date($filters[$key]);}
    if(!empty($filters['from'])&&!empty($filters['to'])&&$filters['from']>$filters['to'])ac_fail('Rentang tanggal terbalik.');
    if(!empty($filters['month'])){$m=(string)$filters['month'];if(!preg_match('/^(0?[1-9]|1[0-2])$/D',$m))ac_fail('Bulan tidak valid.');$where[]="MONTH($alias.transaction_date)=?";$params[]=(int)$m;}
    if(!empty($filters['year'])){$year=(string)$filters['year'];if(!preg_match('/^\d{4}$/D',$year))ac_fail('Tahun tidak valid.');$where[]="YEAR($alias.transaction_date)=?";$params[]=(int)$year;}
    $map=['source'=>'source_type','type'=>'type','classification'=>'classification','account_id'=>'counter_account_id','department_id'=>'department_id','batch'=>'batch','student_id'=>'student_id','vendor_id'=>'vendor_id','payment_account_id'=>'cash_account_id','approval_status'=>'approval_status','payment_status'=>'payment_status','journal_status'=>'journal_status','created_by'=>'created_by'];
    foreach($map as $key=>$column)if(isset($filters[$key])&&$filters[$key]!==''){$value=ac_text((string)$filters[$key],"Filter $key",100);$where[]="$alias.$column=?";$params[]=$value;}
    if(!empty($filters['search'])){$q='%'.ac_text($filters['search'],'Pencarian',100).'%';$where[]="($alias.number LIKE ? OR $alias.source_number LIKE ? OR $alias.description LIKE ? OR $alias.party_name LIKE ?)";array_push($params,$q,$q,$q,$q);}
    return [$where?' WHERE '.implode(' AND ',$where):'',$params];
}
function ac_ledger_sql(mysqli $db):string {
    $sql= "SELECT t.id,CONCAT('transaction:',t.id) AS ledger_id,t.number,t.transaction_date,t.type,t.classification,t.source_type,t.source_id,t.source_number,t.category,t.description,t.amount,t.currency,t.cash_account_id,t.counter_account_id,t.department_id,t.batch,t.student_id,t.vendor_id,t.party_name,t.payment_method,t.approval_status,t.payment_status,t.journal_status,t.created_by,t.created_by_name,t.approved_by_name,t.journal_entry_id,0 AS needs_review FROM accounting_transactions t
    UNION ALL SELECT f.id,CONCAT('legacy:',f.id),CONCAT('LEGACY-FIN-',LPAD(f.id,6,'0')),f.transaction_date,f.type,'unclassified',CASE WHEN f.budget_request_id IS NOT NULL THEN 'budget_approval_legacy' WHEN f.salary_request_id IS NOT NULL THEN 'salary' ELSE 'legacy_finance' END,COALESCE(CAST(f.budget_request_id AS CHAR),CAST(f.salary_request_id AS CHAR),CAST(f.id AS CHAR)),CASE WHEN f.budget_request_id IS NOT NULL THEN CONCAT('RAB-',LPAD(f.budget_request_id,6,'0')) WHEN f.salary_request_id IS NOT NULL THEN CONCAT('PAYROLL-',f.salary_request_id) ELSE CONCAT('FIN-',f.id) END,f.category,f.description,f.amount,'IDR',NULL,NULL,NULL,NULL,NULL,NULL,f.source,f.metode,'unknown','unknown','unposted',f.created_by,COALESCE(e.full_name,u.email),NULL,NULL,1 FROM finance_records f LEFT JOIN accounting_transactions t ON t.legacy_finance_id=f.id LEFT JOIN users u ON u.id=f.created_by LEFT JOIN employees e ON e.user_id=u.id WHERE t.id IS NULL";
    $hasSalary=ac_one($db,"SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='finance_records' AND COLUMN_NAME='salary_request_id'");if(!$hasSalary)$sql=str_replace('f.salary_request_id','NULL',$sql);
    $columns=['id','ledger_id','number','transaction_date','type','classification','source_type','source_id','source_number','category','description','amount','currency','cash_account_id','counter_account_id','department_id','batch','student_id','vendor_id','party_name','payment_method','approval_status','payment_status','journal_status','created_by','created_by_name','approved_by_name','journal_entry_id','needs_review'];
    foreach(['invoice_payment','billing_payment'] as $type){$table=$type==='invoice_payment'?'invoice_records':'billing_pembayaran';if(!ac_table($db,$table))continue;
        $map=['id'=>'p.id','ledger_id'=>"CONCAT('$type:',p.id)",'number'=>"CONCAT('LEGACY-PAY-',p.id)",'transaction_date'=>$type==='invoice_payment'?'DATE(p.created_at)':'DATE(p.tglBayar)','type'=>"'income'",'classification'=>"'unclassified'",'source_type'=>"'$type'",'source_id'=>'CAST(p.id AS CHAR)','source_number'=>$type==='invoice_payment'?"CONCAT('CLIENT-',p.client_id)":'p.noInv','category'=>"'Pembayaran invoice historis'",'description'=>$type==='invoice_payment'?'p.keterangan':'p.statusVerif','amount'=>'p.jumlah','currency'=>"'IDR'",'party_name'=>$type==='invoice_payment'?'c.name':'p.customer','payment_method'=>$type==='invoice_payment'?"'unknown'":'p.metode','approval_status'=>"'unknown'",'payment_status'=>"'unknown'",'journal_status'=>"'unposted'",'created_by'=>$type==='invoice_payment'?'p.created_by':'NULL','created_by_name'=>$type==='invoice_payment'?'u.email':'NULL','needs_review'=>'1'];
        $select=[];foreach($columns as $col)$select[]=$map[$col]??'NULL';$sql.=' UNION ALL SELECT '.implode(',',$select)." FROM $table p ".($type==='invoice_payment'?'LEFT JOIN invoice_clients c ON c.id=p.client_id LEFT JOIN users u ON u.id=p.created_by ':'')."WHERE NOT EXISTS(SELECT 1 FROM accounting_transactions t WHERE t.source_type='$type' AND t.source_id=CAST(p.id AS CHAR))";
    }
    $sql.=" UNION ALL SELECT j.id,CONCAT('journal:',j.id),j.number,j.entry_date,CASE WHEN COALESCE(SUM(IF(a.report_class='cash',l.debit-l.credit,0)),0)>0 THEN 'income' WHEN COALESCE(SUM(IF(a.report_class='cash',l.debit-l.credit,0)),0)<0 THEN 'expense' ELSE 'journal' END,j.event,j.source_type,j.source_id,j.number,'Jurnal akuntansi',j.description,IF(SUM(IF(a.report_class='cash',l.debit-l.credit,0))<>0,ABS(SUM(IF(a.report_class='cash',l.debit-l.credit,0))),SUM(l.debit)),'IDR',NULL,IF(COUNT(DISTINCT l.account_id)=1,MIN(l.account_id),NULL),IF(COUNT(DISTINCT l.department_id)=1,MIN(l.department_id),NULL),IF(COUNT(DISTINCT l.batch)=1,MIN(l.batch),NULL),IF(COUNT(DISTINCT l.student_id)=1,MIN(l.student_id),NULL),IF(COUNT(DISTINCT l.vendor_id)=1,MIN(l.vendor_id),NULL),IF(COUNT(DISTINCT l.party_name)=1,MIN(l.party_name),NULL),'noncash','approved','not_applicable','posted',j.created_by,u.email,NULL,j.id,0 FROM journal_entries j JOIN journal_lines l ON l.journal_entry_id=j.id JOIN accounts a ON a.id=l.account_id LEFT JOIN users u ON u.id=j.created_by WHERE j.status='posted' AND j.event<>'cash_post' GROUP BY j.id";
    return $sql;
}
function ac_ledger(mysqli $db,array $filters,bool $export=false):array {
    [$where,$params]=ac_ledger_filters($filters);$base='('.ac_ledger_sql($db).') x';
    $count=ac_one($db,"SELECT COUNT(*) AS total FROM $base$where",$params);
    $page=max(1,(int)($filters['page']??1));$size=50;
    $sql="SELECT x.*,COALESCE(a.code,(SELECT GROUP_CONCAT(DISTINCT ja.code ORDER BY ja.code SEPARATOR ', ') FROM journal_lines jl JOIN accounts ja ON ja.id=jl.account_id WHERE jl.journal_entry_id=x.journal_entry_id)) AS account_code,a.name AS account_name,b.name AS cash_account_name,d.name AS department_name,CASE WHEN x.type='income' AND x.source_type<>'budget_approval_legacy' THEN x.amount ELSE NULL END AS incoming_amount,CASE WHEN x.type='expense' THEN x.amount ELSE NULL END AS outgoing_amount FROM $base LEFT JOIN accounts a ON a.id=x.counter_account_id LEFT JOIN cash_bank_accounts b ON b.id=x.cash_account_id LEFT JOIN departments d ON d.id=x.department_id$where ORDER BY x.transaction_date DESC,x.ledger_id DESC";
    if(!$export)$sql.=' LIMIT '.$size.' OFFSET '.(($page-1)*$size);
    return ['rows'=>ac_rows($db,$sql,$params),'total'=>(int)$count['total'],'page'=>$page,'page_size'=>$size];
}
function ac_transaction_detail(mysqli $db,string $ledgerId):array {
    if(!preg_match('/^(transaction|legacy|invoice_payment|billing_payment|journal):([1-9]\d*)$/D',$ledgerId,$match))ac_fail('ID buku transaksi tidak valid.');$id=(int)$match[2];
    if($match[1]==='journal'){$journal=ac_journal_detail($db,$id);$source=['type'=>$journal['source_type'],'id'=>$journal['source_id'],'event'=>$journal['event']];if(in_array($journal['source_type'],['billing_invoice','invoice_client','salary','reimbursement','vendor_bill'],true))$source=ac_source($db,$journal['source_type'],$journal['source_id']);elseif($journal['source_type']==='journal')$source['record']=ac_journal_detail($db,(int)$journal['source_id']);return ['legacy'=>false,'journal_only'=>true,'transaction'=>['id'=>$id,'number'=>$journal['number'],'transaction_date'=>$journal['entry_date'],'description'=>$journal['description'],'source_type'=>$journal['source_type'],'source_id'=>$journal['source_id'],'journal_status'=>'posted','created_by'=>$journal['created_by'],'created_at'=>$journal['created_at']??null],'source'=>$source,'journal'=>$journal,'history'=>ac_rows($db,"SELECT * FROM accounting_audit_logs WHERE entity_type='journal' AND entity_id=? ORDER BY id",[(string)$id])];}
    if(in_array($match[1],['invoice_payment','billing_payment'],true)){$source=ac_source($db,$match[1],(string)$id);return ['legacy'=>true,'transaction'=>['id'=>$id,'source_type'=>$match[1],'source_id'=>$id,'amount'=>$source['amount'],'transaction_date'=>$source['date'],'description'=>$source['record']['keterangan']??$source['number'],'party_name'=>$source['record']['customer']??''],'source'=>$source,'journal'=>null,'history'=>[],'notice'=>'Pembayaran invoice historis belum diverifikasi ke jurnal. Dokumen asli tetap disimpan.'];}
    if($match[1]==='legacy'){
        $s=ac_source($db,'legacy_finance',(string)$id);$row=$s['record'];
        $result=['legacy'=>true,'transaction'=>$row,'journal'=>null,'history'=>[],'source'=>$s,'notice'=>'Transaksi historis belum diklasifikasikan/diakui. Status approval, pembayaran dan COA tidak diasumsikan.'];
        if(!empty($row['budget_request_id'])){require_once __DIR__.'/budget_workflow.php';$result['source']=budget_read($db,(int)$row['budget_request_id']);$result['notice']='Catatan approval RAB historis; bukan bukti penerimaan kas.';}
        if(!empty($row['salary_request_id'])){require_once __DIR__.'/salary_workflow.php';$result['source']=salary_read($db,(int)$row['salary_request_id']);}
        return $result;
    }
    $t=ac_one($db,'SELECT t.*,b.name AS cash_account_name,b.account_number AS source_bank_number,d.name AS destination_cash_account_name,a.code AS account_code,a.name AS account_name FROM accounting_transactions t JOIN cash_bank_accounts b ON b.id=t.cash_account_id LEFT JOIN cash_bank_accounts d ON d.id=t.destination_cash_account_id JOIN accounts a ON a.id=t.counter_account_id WHERE t.id=?',[$id]);if(!$t)ac_fail('Transaksi tidak ditemukan.',404);
    $source=$t['source_type']==='cash_transaction'?['type'=>'cash_transaction','id'=>$id,'number'=>$t['number']]:ac_source($db,$t['source_type'],$t['source_id']);
    if($t['source_type']==='salary'){require_once __DIR__.'/salary_workflow.php';$source['record']=salary_read($db,(int)$t['source_id']);}
    if($t['source_type']==='budget_realization'){require_once __DIR__.'/budget_workflow.php';$source['budget']=budget_read($db,(int)$source['record']['budget_request_id']);}
    if($t['student_id'])$source['student']=ac_one($db,'SELECT id,nama_lengkap,level,batch,user_id FROM peserta_intensif WHERE id=?',[(int)$t['student_id']]);
    if($t['vendor_id'])$source['vendor']=ac_one($db,'SELECT id,name,is_active FROM vendors WHERE id=?',[(int)$t['vendor_id']]);
    if($t['department_id'])$source['department']=ac_one($db,'SELECT id,name FROM departments WHERE id=?',[(int)$t['department_id']]);
    $relatedReal=ac_one($db,'SELECT budget_request_id FROM budget_realizations WHERE transaction_id=?',[$id]);if($relatedReal&&!isset($source['budget'])){require_once __DIR__.'/budget_workflow.php';$source['budget']=budget_read($db,(int)$relatedReal['budget_request_id']);}
    $source['accounting_history']=ac_rows($db,"SELECT * FROM accounting_audit_logs WHERE (entity_type=? AND entity_id=?) OR (entity_type='document' AND entity_id=?) ORDER BY id",[$t['source_type'],$t['source_id'],$t['source_type'].':'.$t['source_id']]);
    return ['legacy'=>false,'transaction'=>$t,'source'=>$source,'journal'=>$t['journal_entry_id']?ac_journal_detail($db,(int)$t['journal_entry_id']):null,'history'=>ac_rows($db,"SELECT * FROM accounting_audit_logs WHERE entity_type='transaction' AND entity_id=? ORDER BY id",[(string)$id]),'allocations'=>ac_rows($db,'SELECT p.*,d.number,d.source_type,d.source_id FROM payment_allocations p JOIN accounting_source_documents d ON d.id=p.source_document_id WHERE p.transaction_id=?',[$id])];
}
